-- wattrota veritabanında çalıştırılır. Mevcut tablolar silinmez.

-- Zamanlar Europe/Istanbul yerel saatidir.

DO $$ BEGIN IF current_database() <> 'wattrota' THEN RAISE EXCEPTION 'Önce wattrota veritabanına bağlanın.'; END IF; END $$;

BEGIN;

CREATE SCHEMA wattrota;

CREATE TABLE wattrota."urunler" (
    "urun_id" text NOT NULL,
    "urun_adi" text NOT NULL,
    PRIMARY KEY ("urun_id")
);

INSERT INTO wattrota."urunler" VALUES
('UR01', 'Portland çimentosu'),
('UR02', 'Kalker katkılı çimento'),
('UR03', 'İnce öğütülmüş Portland çimentosu');

DO $$ BEGIN IF (SELECT count(*) FROM wattrota."urunler") <> 3 THEN RAISE EXCEPTION 'urunler: kayıt sayısı uyuşmuyor'; END IF; END $$;

CREATE TABLE wattrota."kaynaklar" (
    "kaynak_id" text NOT NULL,
    "kaynak_adi" text NOT NULL,
    "kaynak_turu" text NOT NULL,
    PRIMARY KEY ("kaynak_id")
);

INSERT INTO wattrota."kaynaklar" VALUES
('H01', 'Öğütme hattı 1', 'ogutme'),
('H02', 'Öğütme hattı 2', 'ogutme'),
('P01', 'Ortak paketleme hattı', 'paketleme'),
('Y01', 'Dökme yükleme', 'dokme_yukleme'),
('Y02', 'Torbalı yükleme', 'torbali_yukleme');

DO $$ BEGIN IF (SELECT count(*) FROM wattrota."kaynaklar") <> 5 THEN RAISE EXCEPTION 'kaynaklar: kayıt sayısı uyuşmuyor'; END IF; END $$;

CREATE TABLE wattrota."kaynak_urun" (
    "kaynak_id" text NOT NULL,
    "urun_id" text NOT NULL,
    "kapasite_ton_saat" bigint NOT NULL,
    "calisma_gucu_kw" bigint NOT NULL,
    PRIMARY KEY ("kaynak_id", "urun_id"),
    FOREIGN KEY ("urun_id") REFERENCES wattrota."urunler" ("urun_id"),
    FOREIGN KEY ("kaynak_id") REFERENCES wattrota."kaynaklar" ("kaynak_id"),
    CHECK (kapasite_ton_saat > 0 AND calisma_gucu_kw >= 0)
);

INSERT INTO wattrota."kaynak_urun" VALUES
('H01', 'UR01', 60, 1800),
('H01', 'UR02', 70, 1800),
