('H02', 'UR01', 70, 2100),
('H02', 'UR02', 80, 2200),
('P01', 'UR01', 80, 100),
('P01', 'UR02', 100, 120),
('P01', 'UR03', 60, 90),
('Y01', 'UR01', 180, 60),
('Y01', 'UR02', 180, 60),
('Y01', 'UR03', 180, 60),
('Y02', 'UR01', 120, 50),
('Y02', 'UR02', 120, 50),
('Y02', 'UR03', 120, 50);

DO $$ BEGIN IF (SELECT count(*) FROM wattrota."kaynak_urun") <> 14 THEN RAISE EXCEPTION 'kaynak_urun: kayıt sayısı uyuşmuyor'; END IF; END $$;

CREATE TABLE wattrota."stok_alanlari" (
    "stok_id" text NOT NULL,
    "urun_id" text NOT NULL,
    "stok_turu" text NOT NULL,
    "minimum_ton" bigint NOT NULL,
    "kapasite_ton" bigint NOT NULL,
    "baslangic_ton" bigint NOT NULL,
    "son_hedef_ton" bigint NOT NULL,
    PRIMARY KEY ("stok_id"),
    FOREIGN KEY ("urun_id") REFERENCES wattrota."urunler" ("urun_id"),
    UNIQUE (urun_id, stok_turu),
    CHECK (minimum_ton >= 0 AND minimum_ton <= baslangic_ton AND baslangic_ton <= kapasite_ton),
    CHECK (son_hedef_ton >= minimum_ton AND son_hedef_ton <= kapasite_ton)
);

