DO $$ BEGIN IF (SELECT count(*) FROM wattrota."stok_alanlari") <> 6 THEN RAISE EXCEPTION 'stok_alanlari: kayıt sayısı uyuşmuyor'; END IF; END $$;

CREATE TABLE wattrota."depo_kurallari" (
    "depo_id" text NOT NULL,
    "toplam_kapasite_ton" bigint NOT NULL,
    PRIMARY KEY ("depo_id"),
    CHECK (toplam_kapasite_ton > 0)
);

