DO $$ BEGIN IF (SELECT count(*) FROM wattrota."depo_kurallari") <> 1 THEN RAISE EXCEPTION 'depo_kurallari: kayıt sayısı uyuşmuyor'; END IF; END $$;

CREATE TABLE wattrota."rota_tanimlari" (
    "rota_id" text NOT NULL,
    "urun_id" text NOT NULL,
    "teslim_turu" text NOT NULL,
    PRIMARY KEY ("rota_id"),
    FOREIGN KEY ("urun_id") REFERENCES wattrota."urunler" ("urun_id"),
    UNIQUE (rota_id, urun_id, teslim_turu)
);

