DO $$ BEGIN IF (SELECT count(*) FROM wattrota."rota_tanimlari") <> 6 THEN RAISE EXCEPTION 'rota_tanimlari: kayıt sayısı uyuşmuyor'; END IF; END $$;

CREATE TABLE wattrota."rotalar" (
    "rota_id" text NOT NULL,
    "urun_id" text NOT NULL,
    "teslim_turu" text NOT NULL,
    "adim_no" bigint NOT NULL,
    "islem_turu" text NOT NULL,
    "girdi_stok_turu" text NOT NULL,
    "cikti_stok_turu" text NOT NULL,
    PRIMARY KEY ("rota_id", "adim_no"),
    FOREIGN KEY ("urun_id") REFERENCES wattrota."urunler" ("urun_id"),
    FOREIGN KEY (rota_id, urun_id, teslim_turu) REFERENCES wattrota.rota_tanimlari (rota_id, urun_id, teslim_turu),
    CHECK (adim_no > 0)
);

