CREATE TABLE wattrota."rota_kaynaklari" (
    "rota_id" text NOT NULL,
    "adim_no" bigint NOT NULL,
    "kaynak_id" text NOT NULL,
    PRIMARY KEY ("rota_id", "adim_no", "kaynak_id"),
    FOREIGN KEY ("kaynak_id") REFERENCES wattrota."kaynaklar" ("kaynak_id"),
    FOREIGN KEY (rota_id, adim_no) REFERENCES wattrota.rotalar (rota_id, adim_no)
);

