CREATE TABLE wattrota."siparisler" (
    "siparis_id" text NOT NULL,
    "urun_id" text NOT NULL,
    "miktar_ton" bigint NOT NULL,
    "teslim_turu" text NOT NULL,
    "rota_id" text NOT NULL,
    "gelis_zamani" timestamp without time zone NOT NULL,
    "en_erken_yukleme" timestamp without time zone NOT NULL,
    "teslim_zamani" timestamp without time zone NOT NULL,
    PRIMARY KEY ("siparis_id"),
    FOREIGN KEY ("urun_id") REFERENCES wattrota."urunler" ("urun_id"),
    FOREIGN KEY (rota_id, urun_id, teslim_turu) REFERENCES wattrota.rota_tanimlari (rota_id, urun_id, teslim_turu),
    CHECK (miktar_ton > 0),
    CHECK (gelis_zamani <= en_erken_yukleme AND en_erken_yukleme < teslim_zamani)
);

