CREATE TABLE wattrota."is_emirleri" (
    "is_emri_id" text NOT NULL,
    "urun_id" text NOT NULL,
    "islem_turu" text NOT NULL,
    "miktar_ton" bigint NOT NULL,
    "serbest_birakma" timestamp without time zone NOT NULL,
    "tamamlanma_siniri" timestamp without time zone NOT NULL,
    "bolunebilir" boolean NOT NULL,
    PRIMARY KEY ("is_emri_id"),
    FOREIGN KEY ("urun_id") REFERENCES wattrota."urunler" ("urun_id"),
    CHECK (miktar_ton > 0 AND serbest_birakma < tamamlanma_siniri)
);

