CREATE TABLE wattrota."is_emri_siparis_baglantisi" (
    "is_emri_id" text NOT NULL,
    "siparis_id" text NOT NULL,
    "tahsis_ton" bigint NOT NULL,
    PRIMARY KEY ("is_emri_id", "siparis_id"),
    FOREIGN KEY ("is_emri_id") REFERENCES wattrota."is_emirleri" ("is_emri_id"),
    FOREIGN KEY ("siparis_id") REFERENCES wattrota."siparisler" ("siparis_id"),
    CHECK (tahsis_ton > 0)
);

