CREATE TABLE wattrota."isletme_kurallari" (
    "kaynak_id" text NOT NULL,
    "minimum_uretim_saat" bigint NOT NULL,
    "minimum_durus_saat" bigint NOT NULL,
    "baslangicta_aktif" boolean NOT NULL,
    "baslangic_durum_suresi_saat" bigint NOT NULL,
    "baslangic_urun_ayari" text NOT NULL,
    "baslatma_enerjisi_kwh" bigint NOT NULL,
    "baslatma_elektrik_disi_gider_tl" bigint NOT NULL,
    PRIMARY KEY ("kaynak_id"),
    FOREIGN KEY ("kaynak_id") REFERENCES wattrota."kaynaklar" ("kaynak_id"),
    FOREIGN KEY ("baslangic_urun_ayari") REFERENCES wattrota."urunler" ("urun_id"),
    CHECK (minimum_uretim_saat >= 1 AND minimum_durus_saat >= 1),
    CHECK (baslangic_durum_suresi_saat >= 0 AND baslatma_enerjisi_kwh >= 0 AND baslatma_elektrik_disi_gider_tl >= 0)
);

