CREATE TABLE wattrota."urun_gecisleri" (
    "kaynak_id" text NOT NULL,
    "onceki_urun" text NOT NULL,
    "sonraki_urun" text NOT NULL,
    "hazirlik_saat" bigint NOT NULL,
    "hazirlik_gucu_kw" bigint NOT NULL,
    "elektrik_disi_gider_tl" bigint NOT NULL,
    PRIMARY KEY ("kaynak_id", "onceki_urun", "sonraki_urun"),
    FOREIGN KEY ("kaynak_id") REFERENCES wattrota."kaynaklar" ("kaynak_id"),
    FOREIGN KEY ("onceki_urun") REFERENCES wattrota."urunler" ("urun_id"),
    FOREIGN KEY ("sonraki_urun") REFERENCES wattrota."urunler" ("urun_id"),
    CHECK (onceki_urun <> sonraki_urun),
    CHECK (hazirlik_saat >= 1 AND hazirlik_gucu_kw >= 0 AND elektrik_disi_gider_tl >= 0)
);

