CREATE TABLE wattrota."tesis_takvimi" (
    "tarih_saat" timestamp without time zone NOT NULL,
    "temel_yuk_kw" bigint NOT NULL,
    "guc_siniri_kw" bigint NOT NULL,
    PRIMARY KEY ("tarih_saat"),
    CHECK (temel_yuk_kw >= 0 AND guc_siniri_kw >= temel_yuk_kw)
);

