CREATE TABLE wattrota."kaynak_takvimi" (
    "kaynak_id" text NOT NULL,
    "tarih_saat" timestamp without time zone NOT NULL,
    "kullanilabilir" boolean NOT NULL,
    PRIMARY KEY ("kaynak_id", "tarih_saat"),
    FOREIGN KEY ("kaynak_id") REFERENCES wattrota."kaynaklar" ("kaynak_id"),
    FOREIGN KEY (tarih_saat) REFERENCES wattrota.tesis_takvimi (tarih_saat)
);

