DO $$ BEGIN IF (SELECT count(*) FROM wattrota."kaynak_takvimi") <> 360 THEN RAISE EXCEPTION 'kaynak_takvimi: kayıt sayısı uyuşmuyor'; END IF; END $$;

CREATE TABLE wattrota."bakimlar" (
    "kaynak_id" text NOT NULL,
    "baslangic" timestamp without time zone NOT NULL,
    "bitis" timestamp without time zone NOT NULL,
    PRIMARY KEY ("kaynak_id", "baslangic"),
    FOREIGN KEY ("kaynak_id") REFERENCES wattrota."kaynaklar" ("kaynak_id"),
    CHECK (baslangic < bitis)
);

