DO $$ BEGIN IF (SELECT count(*) FROM wattrota."bakimlar") <> 4 THEN RAISE EXCEPTION 'bakimlar: kayıt sayısı uyuşmuyor'; END IF; END $$;

CREATE TABLE wattrota."fiyatlar" (
    "tarih_saat" timestamp without time zone NOT NULL,
    "PTF (TL/MWh)" double precision NOT NULL,
    PRIMARY KEY ("tarih_saat"),
    CHECK ("PTF (TL/MWh)" >= 0)
);

