DO $$ BEGIN IF (SELECT count(*) FROM wattrota."fiyatlar") <> 72 THEN RAISE EXCEPTION 'fiyatlar: kayıt sayısı uyuşmuyor'; END IF; END $$;

CREATE TABLE wattrota."referans_plan" (
    "kaynak_id" text NOT NULL,
    "tarih_saat" timestamp without time zone NOT NULL,
    "durum" text NOT NULL,
    "urun_id" text,
    "is_emri_id" text,
    PRIMARY KEY ("kaynak_id", "tarih_saat"),
    FOREIGN KEY ("urun_id") REFERENCES wattrota."urunler" ("urun_id"),
    FOREIGN KEY ("kaynak_id") REFERENCES wattrota."kaynaklar" ("kaynak_id"),
    FOREIGN KEY ("is_emri_id") REFERENCES wattrota."is_emirleri" ("is_emri_id"),
    FOREIGN KEY (tarih_saat) REFERENCES wattrota.tesis_takvimi (tarih_saat),
    CHECK (durum IN ('uretim', 'hazirlik', 'kapali')),
    CHECK ((durum = 'uretim' AND urun_id IS NOT NULL AND is_emri_id IS NOT NULL) OR (durum = 'hazirlik' AND urun_id IS NOT NULL AND is_emri_id IS NULL) OR (durum = 'kapali' AND urun_id IS NULL AND is_emri_id IS NULL))
);

