DO $$ BEGIN IF (SELECT count(*) FROM wattrota."referans_plan") <> 216 THEN RAISE EXCEPTION 'referans_plan: kayıt sayısı uyuşmuyor'; END IF; END $$;

CREATE TABLE wattrota."referans_yuklemeler" (
    "siparis_id" text NOT NULL,
    "kaynak_id" text NOT NULL,
    "tarih_saat" timestamp without time zone NOT NULL,
    "miktar_ton" bigint NOT NULL,
    PRIMARY KEY ("siparis_id", "kaynak_id", "tarih_saat"),
    FOREIGN KEY ("kaynak_id") REFERENCES wattrota."kaynaklar" ("kaynak_id"),
    FOREIGN KEY ("siparis_id") REFERENCES wattrota."siparisler" ("siparis_id"),
    FOREIGN KEY (tarih_saat) REFERENCES wattrota.tesis_takvimi (tarih_saat),
    CHECK (miktar_ton > 0)
);

